90		var lastActive *time.Time
91		if !s.LastActive.IsZero() {
92			active := s.LastActive
93			lastActive = &active
94		}
95	
96		payload := trailResumeSessionContextJSON{
97			SessionID:    s.SessionID,
98			Agent:        s.Agent,
99			LastPrompt:   s.LastPrompt,
100			LastActive:   lastActive,
