133	func newTrailResumeCmd() *cobra.Command {
134		var opts trailResumeOptions
135	
136		cmd := &cobra.Command{
137			Use:   "resume [<trail>]",
138			Short: "Resume a trail's agent session",
139			Long: `Resume an agent session for a trail.
140	
141	The trail may be given as the first argument or via --trail, as a number, id, or
142	branch. Without one, the trail for the current branch is used.
143	
144	By default, interactive terminals show the trail context, restore the checkpoint
145	sessions on the trail branch, and ask whether Entire should start the agent. If
146	there are multiple sessions in the checkpoint, you can choose which one to
147	start. Non-interactive runs show the same context and print resume commands for
148	the latest checkpoint on the trail branch. Use --session or --checkpoint to
149	resume an exact session or checkpoint.
150	
151	Use --repo to assert the GitHub repository for copied commands, and --branch
152	with a trail number or id to assert the branch you expect the trail to be
153	attached to. If either assertion does not match the current checkout or trail,
154	resume stops before checking anything out.`,
155			Args: cobra.MaximumNArgs(1),
156			RunE: func(cmd *cobra.Command, args []string) error {
157				selector, err := parseOptionalTrailSelector(args, opts.Selector)
158				if err != nil {
159					return err
160				}
161				opts.Selector = selector
162				if err := validateTrailResumeOptions(opts); err != nil {
163					return err
164				}
165				external.DiscoverAndRegister(cmd.Context())
166				return runTrailResume(cmd, opts)
167			},
168		}
169	
170		cmd.Flags().StringVar(&opts.Selector, "trail", "", "Trail to resume (number, id, or branch; defaults to the current branch's trail)")
171		cmd.Flags().StringVar(&opts.ExpectedRepo, "repo", "", "Expected GitHub repository (owner/name); fails if the current checkout points elsewhere")
172		cmd.Flags().StringVar(&opts.ExpectedBranch, "branch", "", "Expected trail branch; fails if the trail is attached to a different branch")
173		cmd.Flags().StringVar(&opts.SessionID, "session", "", "Resume a specific known local session on the trail branch")
174		cmd.Flags().StringVar(&opts.CheckpointID, "checkpoint", "", "Resume a specific checkpoint on the trail branch")
175		cmd.Flags().BoolVarP(&opts.Force, "force", "f", false, "Skip prompts and overwrite existing session logs from checkpoints")
176		cmd.Flags().BoolVar(&opts.JSON, "json", false, "Output trail resume context as JSON")
177		cmd.Flags().BoolVar(&opts.NoResume, "no-resume", false, "Show trail resume context without restoring or resuming a session")
178	
179		return cmd
180	}
