182	func validateTrailResumeOptions(opts trailResumeOptions) error {
183		if strings.TrimSpace(opts.SessionID) != "" && strings.TrimSpace(opts.CheckpointID) != "" {
184			return errors.New("cannot combine --session and --checkpoint")
185		}
186		if opts.JSON && !opts.NoResume {
187			return errors.New("--json can only be used with --no-resume")
188		}
189		if opts.NoResume && (strings.TrimSpace(opts.SessionID) != "" || strings.TrimSpace(opts.CheckpointID) != "") {
190			return errors.New("cannot combine --no-resume with --session or --checkpoint")
191		}
192		if _, err := parseTrailResumeRepoFlag(opts.ExpectedRepo); err != nil {
193			return fmt.Errorf("validate --repo: %w", err)
194		}
195		if checkpointID := strings.TrimSpace(opts.CheckpointID); checkpointID != "" {
196			if err := id.Validate(checkpointID); err != nil {
197				return fmt.Errorf("validate --checkpoint: %w", err)
198			}
199		}
200		return nil
201	}
