203	func runTrailResume(cmd *cobra.Command, opts trailResumeOptions) error {
204		return runAuthenticatedDataAPI(cmd.Context(), cmd.ErrOrStderr(), trailInsecureHTTP(cmd), func(ctx context.Context, client *api.Client) error {
205			forge, owner, repo, err := resolveTrailRemote(ctx)
206			if err != nil {
207				return err
208			}
209			targetRepo := trailResumeRepository{Forge: forge, Owner: owner, Repo: repo}
210			expectedRepo, err := parseTrailResumeRepoFlag(opts.ExpectedRepo)
211			if err != nil {
212				return fmt.Errorf("validate --repo: %w", err)
213			}
214			if err := validateTrailResumeExpectedRepo(targetRepo, expectedRepo); err != nil {
215				return err
216			}
217			if expectedRepo.Repo != "" {
218				forge, owner, repo = expectedRepo.Forge, expectedRepo.Owner, expectedRepo.Repo
219			}
220	
221			found, err := resolveTrailBySelector(ctx, client, forge, owner, repo, opts.Selector, opts.ExpectedBranch)
222			if err != nil {
223				return err
224			}
225			branch := strings.TrimSpace(found.Branch)
226			if branch == "" {
227				return fmt.Errorf("%s has no branch to resume", describeTrailRef(found))
228			}
229			if err := validateTrailResumeExpectedBranch(found, opts.ExpectedBranch); err != nil {
230				return err
231			}
232	
233			sessions, sessionsSkipped, sessionErr := resolveTrailResumeSessionContexts(ctx, branch)
234			sessions, sessionsSkipped, sessionsUnavailable := knownTrailResumeSessionsForContext(sessions, sessionsSkipped, sessionErr)
235			if sessionsUnavailable != "" {
236				fmt.Fprintf(cmd.ErrOrStderr(), "Warning: could not load trail checkpoint sessions: %s\n", sessionsUnavailable)
237			}
238	
239			findings, findingsErr := loadTrailResumeFindingsContext(ctx, client, found.ID)
240			if findingsErr != nil {
241				findings.Unavailable = findingsErr.Error()
242				fmt.Fprintf(cmd.ErrOrStderr(), "Warning: could not load trail findings: %v\n", findingsErr)
243			}
244	
245			resumeCtx := buildTrailResumeContextForRepoWithSkipped(*found, sessions, sessionsUnavailable, sessionsSkipped, findings, owner+"/"+repo)
246			if opts.JSON {
247				return encodeTrailResumeContextJSON(cmd.OutOrStdout(), resumeCtx)
248			}
249	
250			printTrailResumeContext(cmd.OutOrStdout(), resumeCtx)
251			if opts.NoResume {
252				return nil
253			}
254	
255			if opts.CheckpointID != "" {
256				return resumeTrailCheckpoint(ctx, cmd, branch, id.CheckpointID(opts.CheckpointID), "", opts.Force)
257			}
258	
259			if opts.SessionID != "" {
260				sessionCtx, ok := findTrailResumeSession(resumeCtx.Sessions, opts.SessionID)
261				if ok {
262					return resumeTrailCheckpoint(ctx, cmd, branch, id.CheckpointID(sessionCtx.CheckpointID), opts.SessionID, opts.Force)
263				}
264				return resumeTrailLatest(ctx, cmd, branch, opts.Force, opts.SessionID)
265			}
266	
267			if interactive.CanPromptInteractively() && len(resumeCtx.Sessions) > 1 {
268				return runTrailResumePicker(ctx, cmd, branch, resumeCtx.Sessions, opts.Force)
269			}
270	
271			return resumeTrailLatest(ctx, cmd, branch, opts.Force, "")
272		})
273	}
