275	func parseTrailResumeRepoFlag(value string) (trailResumeRepository, error) {
276		value = strings.TrimSpace(value)
277		if value == "" {
278			return trailResumeRepository{}, nil
279		}
280		owner, repo, err := parseGitHubURL(value)
281		if err != nil {
282			return trailResumeRepository{}, err
283		}
284		return trailResumeRepository{Forge: "gh", Owner: owner, Repo: repo}, nil
285	}
