287	func validateTrailResumeExpectedRepo(current, expected trailResumeRepository) error {
288		if strings.TrimSpace(expected.Repo) == "" {
289			return nil
290		}
291		if current.Forge == expected.Forge &&
292			strings.EqualFold(current.Owner, expected.Owner) &&
293			strings.EqualFold(current.Repo, expected.Repo) {
294			return nil
295		}
296		return fmt.Errorf("this command targets repository %s/%s, but the current checkout is %s/%s", expected.Owner, expected.Repo, current.Owner, current.Repo)
297	}
