299	func validateTrailResumeExpectedBranch(found *api.TrailResource, expectedBranch string) error {
300		expectedBranch = strings.TrimSpace(expectedBranch)
301		if expectedBranch == "" {
302			return nil
303		}
304		actualBranch := strings.TrimSpace(found.Branch)
305		if actualBranch == expectedBranch {
306			return nil
307		}
308		return fmt.Errorf("%s is attached to branch %q, not expected branch %q", describeTrailRef(found), actualBranch, expectedBranch)
309	}
