318	func resumeTrailLatest(ctx context.Context, cmd *cobra.Command, branch string, force bool, preferredSessionID string) error {
319		w := cmd.OutOrStdout()
320		errW := cmd.ErrOrStderr()
321	
322		if !ensureTrailResumeBranchAvailable(ctx, w, branch) {
323			return nil
324		}
325		proceed, err := switchToBranchForResume(ctx, w, errW, branch, trailResumeSkipBranchPrompts(force))
326		if err != nil || !proceed {
327			return err
328		}
329		sessions, err := restoreFromCurrentBranch(ctx, w, errW, branch, force)
330		if err != nil {
331			return err
332		}
333		return continueTrailRestoredSessions(ctx, cmd, sessions, preferredSessionID, force)
334	}
