374	func printTrailRestoredSessionSummary(w io.Writer, sessions []strategy.RestoredSession) {
375		checkpointID := restoredSessionsCheckpointID(sessions)
376		switch {
377		case checkpointID != "" && len(sessions) > 1:
378			fmt.Fprintf(w, "\n✓ Restored checkpoint %s (%d sessions).\n", checkpointID, len(sessions))
379		case checkpointID != "" && len(sessions) == 1:
380			fmt.Fprintf(w, "✓ Restored checkpoint %s (1 session).\n", checkpointID)
381		case len(sessions) > 1:
382			fmt.Fprintf(w, "\n✓ Restored %d checkpoint sessions.\n", len(sessions))
383		case len(sessions) == 1:
384			fmt.Fprintf(w, "✓ Restored checkpoint session %s.\n", sessions[0].SessionID)
385		}
386		if len(sessions) > 0 && trailRestoredSessionsAreAllReviewOrInvestigation(sessions) {
387			fmt.Fprintln(w, "  Only review/investigation checkpoint sessions were found; these are transcript logs and may not appear as trail UI sessions.")
388		}
389	}
