391	func displayTrailRestoredSessions(w io.Writer, sessions []strategy.RestoredSession) error {
392		if len(sessions) == 0 {
393			return nil
394		}
395		choices := buildTrailResumeRestoredSessionChoices(sessions)
396		printTrailRestoredSessionSummary(w, sessions)
397		if len(choices) > 1 {
398			fmt.Fprintln(w, "To continue:")
399		} else {
400			fmt.Fprintln(w, "\nTo continue this checkpoint session:")
401		}
402	
403		isMulti := len(choices) > 1
404		mostRecentSessionID := mostRecentRestoredSessionID(sessions)
405		for _, choice := range choices {
406			sessionAgent, err := strategy.ResolveAgentForRewind(choice.Session.Agent)
407			if err != nil {
408				return fmt.Errorf("failed to resolve agent for session %s: %w", choice.SessionID, err)
409			}
410			printSessionCommand(w, sessionAgent.FormatResumeCommand(choice.SessionID), trailRestoredSessionPrompt(choice.Session), isMulti, choice.SessionID == mostRecentSessionID)
411		}
412		return nil
413	}
