415	func mostRecentRestoredSessionID(sessions []strategy.RestoredSession) string {
416		var latestID string
417		var latestTime time.Time
418		for _, session := range sessions {
419			if session.SessionID == "" || session.CreatedAt.IsZero() {
420				continue
421			}
422			if latestID == "" || session.CreatedAt.After(latestTime) {
423				latestID = session.SessionID
424				latestTime = session.CreatedAt
425			}
426		}
427		return latestID
428	}
