430	func resolveTrailResumeSessionContexts(ctx context.Context, branch string) ([]trailResumeSessionContext, int, error) {
431		sessions, skipped, err := resolveTrailCheckpointSessions(ctx, branch)
432		if err == nil && len(sessions) > 0 {
433			return sessions, skipped, nil
434		}
435	
436		items, localErr := resolveTrailResumeSessions(ctx, branch)
437		if localErr != nil {
438			if err != nil {
439				return nil, 0, err
440			}
441			return nil, skipped, localErr
442		}
443		localSessions := trailResumeSessionContextsFromLocal(branch, items)
444		if len(localSessions) > 0 {
445			return localSessions, skipped, nil
446		}
447		return sessions, skipped, err
448	}
