450	func resolveTrailCheckpointSessions(ctx context.Context, branch string) ([]trailResumeSessionContext, int, error) {
451		repo, err := openRepository(ctx)
452		if err != nil {
453			return nil, 0, fmt.Errorf("not a git repository: %w", err)
454		}
455		defer repo.Close()
456	
457		result, err := findBranchCheckpointsForBranchRef(repo, branch)
458		if err != nil {
459			return nil, 0, err
460		}
461		if len(result.checkpointIDs) == 0 {
462			return nil, 0, nil
463		}
464	
465		stores, err := checkpoint.Open(ctx, repo, checkpoint.OpenOptions{BlobFetcher: FetchBlobsByHash})
466		if err != nil {
467			return nil, 0, fmt.Errorf("open checkpoint store: %w", err)
468		}
469		store := stores.Persistent
470		refs := stores.Refs()
471		if refs.ReadBootstrappableFromOrigin() {
472			promoteRemoteTrackingPrimary(ctx, repo, refs)
473		}
474	
475		sessions := make([]trailResumeSessionContext, 0)
476		skipped := 0
477		for _, checkpointID := range result.checkpointIDs {
478			checkpointSessions, checkpointSkipped, readErr := readTrailCheckpointSessionContexts(ctx, store, checkpointID)
479			if readErr != nil {
480				return nil, 0, readErr
481			}
482			sessions = append(sessions, checkpointSessions...)
483			skipped += checkpointSkipped
484		}
485	
486		sort.SliceStable(sessions, func(i, j int) bool {
487			return sessions[i].LastActive.After(sessions[j].LastActive)
488		})
489		return sessions, skipped, nil
490	}
