492	func readTrailCheckpointSessionContexts(ctx context.Context, store checkpointInfoReader, checkpointID id.CheckpointID) ([]trailResumeSessionContext, int, error) {
493		summary, err := checkpoint.ReadCheckpoint(ctx, store, checkpointID)
494		if err != nil {
495			return nil, 0, fmt.Errorf("read checkpoint %s: %w", checkpointID, err)
496		}
497	
498		sessions := make([]trailResumeSessionContext, 0, len(summary.Sessions))
499		skipped := 0
500		for i := range summary.Sessions {
501			content, contentErr := readTrailCheckpointSessionContent(ctx, store, checkpointID, i)
502			if contentErr != nil {
503				skipped++
504				continue
505			}
506			metadata := content.Metadata
507			if strings.TrimSpace(metadata.SessionID) == "" {
508				continue
509			}
510			prompt := strategy.ExtractFirstPrompt(content.Prompts)
511			if prompt == "" {
512				prompt = strings.TrimSpace(metadata.ReviewPrompt)
513			}
514			sessions = append(sessions, trailResumeSessionContext{
515				SessionID:    metadata.SessionID,
516				Agent:        string(metadata.Agent),
517				LastPrompt:   prompt,
518				LastActive:   metadata.CreatedAt,
519				CheckpointID: checkpointID.String(),
520			})
521		}
522	
523		if len(sessions) == 0 {
524			info, infoErr := readCheckpointInfoFromStore(ctx, store, checkpointID)
525			if infoErr == nil && strings.TrimSpace(info.SessionID) != "" {
526				sessions = append(sessions, trailResumeSessionContext{
527					SessionID:    info.SessionID,
528					Agent:        string(info.Agent),
529					LastActive:   info.CreatedAt,
530					CheckpointID: checkpointID.String(),
531				})
532			}
533		}
534	
535		sort.SliceStable(sessions, func(i, j int) bool {
536			return sessions[i].LastActive.After(sessions[j].LastActive)
537		})
538		return sessions, skipped, nil
539	}
