541	func readTrailCheckpointSessionContent(
542		ctx context.Context,
543		store checkpointInfoReader,
544		checkpointID id.CheckpointID,
545		sessionIndex int,
546	) (*checkpoint.SessionContent, error) {
547		if reader, ok := store.(interface {
548			ReadSessionMetadataAndPrompts(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*checkpoint.Metadata, string, error)
549		}); ok {
550			metadata, prompts, err := reader.ReadSessionMetadataAndPrompts(ctx, checkpointID, sessionIndex)
551			if err != nil {
552				return nil, err //nolint:wrapcheck // Contextualized by caller.
553			}
554			if metadata == nil {
555				return nil, errors.New("checkpoint session metadata missing")
556			}
557			return &checkpoint.SessionContent{Metadata: *metadata, Prompts: prompts}, nil
558		}
559		metadata, err := store.ReadSessionMetadata(ctx, checkpointID, sessionIndex)
560		if err != nil {
561			return nil, err //nolint:wrapcheck // Contextualized by caller.
562		}
563		if metadata == nil {
564			return nil, errors.New("checkpoint session metadata missing")
565		}
566		return &checkpoint.SessionContent{Metadata: *metadata}, nil
567	}
