569	func resolveTrailResumeSessions(ctx context.Context, branch string) ([]resumableSession, error) {
570		states, err := strategy.ListSessionStates(ctx)
571		if err != nil {
572			return nil, fmt.Errorf("failed to list sessions: %w", err)
573		}
574		states = filterResumableSessions(states)
575	
576		repo, err := openRepository(ctx)
577		if err != nil {
578			items := make([]resumableSession, 0, len(states))
579			for _, state := range states {
580				if state == nil {
581					continue
582				}
583				items = append(items, resumableSession{
584					state:        state,
585					branch:       state.Branch,
586					checkpointID: state.LastCheckpointID,
587				})
588			}
589			return items, nil
590		}
591		defer repo.Close()
592	
593		items := resolveResumableBranches(repo, states)
594		for i := range items {
595			if items[i].branch == "" && items[i].state != nil && items[i].state.Branch == branch {
596				items[i].branch = branch
597			}
598		}
599		return items, nil
600	}
