699	func buildTrailResumeCommands(ctx trailResumeContext) []string {
700		selector := trailResumeSelectorForCommands(ctx.Trail)
701		if selector == "" {
702			return nil
703		}
704		arg := shellArg(selector)
705		resumeCommand := "entire trail resume " + arg
706		if repo := strings.TrimSpace(ctx.Trail.Repo); repo != "" {
707			resumeCommand += " --repo " + shellArg(repo)
708		}
709		if branch := strings.TrimSpace(ctx.Trail.Branch); branch != "" {
710			resumeCommand += " --branch " + shellArg(branch)
711		}
712		commands := []string{
713			"entire trail finding " + arg + " --json",
714			resumeCommand,
715		}
716		if ctx.DefaultResume != nil && ctx.DefaultResume.CheckpointID != "" {
717			commands = append(commands, resumeCommand+" --checkpoint "+shellArg(ctx.DefaultResume.CheckpointID))
718		}
719		for _, session := range ctx.Sessions {
720			commands = append(commands, resumeCommand+" --session "+shellArg(session.SessionID))
721		}
722		return commands
723	}
