946				return trailRestoredSessionSortRank(sorted[i]) < trailRestoredSessionSortRank(sorted[j])
947			}
948			return sorted[i].CreatedAt.After(sorted[j].CreatedAt)
949		})
950	
951		choices := make([]trailResumeRestoredSessionChoice, 0, len(sorted))
952		for i, session := range sorted {
953			choices = append(choices, trailResumeRestoredSessionChoice{
954				SessionID: session.SessionID,
955				Label:     trailRestoredSessionChoiceLabel(session, i == 0 && len(sorted) > 1),
956				Session:   session,
957			})
958		}
959		return choices
960	}
