1088	func launchTrailRestoredSession(ctx context.Context, w io.Writer, session strategy.RestoredSession) error {
1089		resumeAgent, err := strategy.ResolveAgentForRewind(session.Agent)
1090		if err != nil {
1091			return fmt.Errorf("failed to resolve agent for session %s: %w", session.SessionID, err)
1092		}
1093		resumeCmd := resumeAgent.FormatResumeCommand(session.SessionID)
1094		cmd, ok, err := agent.NewResumeForegroundCommand(ctx, resumeAgent.Name(), session.SessionID)
1095		if !ok {
1096			fmt.Fprintf(w, "\nTo continue this session:\n")
1097			printSessionCommand(w, resumeCmd, session.Prompt, false, true)
1098			return nil
1099		}
1100		if err != nil {
1101			fmt.Fprintf(w, "\nCould not launch %s: %v\n", resumeCmd, err)
1102			fmt.Fprintf(w, "\nTo continue this session:\n")
1103			printSessionCommand(w, resumeCmd, session.Prompt, false, true)
1104			return nil
1105		}
1106		fmt.Fprintf(w, "\nLaunching: %s\n", resumeCmd)
1107		if err := cmd.Run(); err != nil {
1108			var exitErr *exec.ExitError
1109			if errors.As(err, &exitErr) {
1110				return nil
1111			}
1112			return fmt.Errorf("resume command failed: %w", err)
1113		}
1114		return nil
1115	}
